design_text:
{
  "site_summary": "A bright indirect courtyard with low moisture and fast-draining gravel pots, featuring no pets in the household.",
  "layout_strategy": "The scheme stacks in three distinct height layers: trailing succulents cascade from wall-mounted pots at eye level, architectural rosette succulents fill the mid-height containers against the wall, and low-growing textural succulents carpet the base gravel layer.",
  "combination_logic": "The combination relies on contrasting architectural forms and textures, pairing the rosettes of Haworthia with the weeping, bead-like stems of Sedum morganianum and the powdery, open rosettes of Sedum weinbergii. The monochromatic green and silver tones remain stable year-round, while changes in light angle create subtle shifts in shadow and highlight across the succulent leaves.",
  "zones": [
    {
      "zone_name": "Upper Cascade",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "on wall-mounted brackets at eye level, receiving bright indirect light from above with no direct sun.",
      "plants": [
        {
          "scientific_name": "Sedum morganianum",
          "common_name": "Burro's Tail",
          "why": "Fits the bright indirect light and low moisture requirements while providing a dramatic trailing habit.",
          "role_in_combination": "Contributes soft, weeping vertical lines that contrast sharply with the rigid upright and rosette shapes in the mid and ground layers."
        }
      ],
      "maintenance": [
        "Water thoroughly only when the soil is completely dry every 3 to 4 weeks.",
        "Fertilize lightly with a diluted succulent formula once in spring.",
        "Handle gently to avoid dropping delicate plump leaves."
      ]
    },
    {
      "zone_name": "Mid-Level Architecture",
      "zone_role": "focal",
      "layer": "mid",
      "placement": "in waist-height ceramic pots set against the main courtyard wall, in bright indirect light.",
      "plants": [
        {
          "scientific_name": "Haworthia subfasciata",
          "common_name": "Little Zebra Plant",
          "why": "Thrives in bright indirect light and low moisture, fitting the gravel-pot drainage profile.",
          "role_in_combination": "Provides striking dark green foliage with white textural bands, offering a strong geometric focal point that anchors the mid-layer."
        },
        {
          "scientific_name": "Haworthia species",
          "common_name": "Haworthia",
          "why": "Adapted to low-moisture conditions and indirect light environments.",
          "role_in_combination": "Complements the Little Zebra Plant with varied leaf patterning and compact rosette structure."
        }
      ],
      "maintenance": [
        "Water every 3 weeks allowing the fast-draining gravel mix to dry completely.",
        "Inspect leaves periodically for mealybugs.",
        "Repot every 2 to 3 years into slightly larger pots using a gritty succulent mix."
      ]
    },
    {
      "zone_name": "Ground Carpet",
      "zone_role": "groundcover",
      "layer": "ground",
      "placement": "in low, wide gravel-filled containers along the floor perimeter, receiving ambient bright indirect light.",
      "plants": [
        {
          "scientific_name": "Sedum weinbergii",
          "common_name": "Ghost Plant",
          "why": "Low-growing succulent that thrives in low moisture and fast-draining gravel substrates.",
          "role_in_combination": "Spreads laterally with fleshy, powdery lavender-grey rosettes that contrast in color and form with the vertical and mid-level greens."
        }
      ],
      "maintenance": [
        "Water sparingly every 3 to 4 weeks at the soil base.",
        "Prune back leggy stems in early spring to maintain a dense carpet habit.",
        "Remove any dead lower leaves to prevent fungal issues."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all containers to ensure complete dry-out between waterings.",
      "frequency": "every 3 weeks",
      "season": "summer"
    },
    {
      "task": "Clear accumulated dust from the succulent leaves using a soft brush.",
      "frequency": "monthly",
      "season": "spring"
    },
    {
      "task": "Reduce watering frequency as ambient temperatures drop and evaporation slows.",
      "frequency": "every 5 to 6 weeks",
      "season": "winter"
    }
  ],
  "care_cautions": [
    "Overwatering the Sedum morganianum in the hanging baskets can easily cause root rot and stem drop due to water retention in dense potting mixes.",
    "The Sedum weinbergii in the ground zone may suffer from etiolation or leaf drop if the courtyard receives insufficient ambient light reflection during overcast winter months."
  ],
  "pet_safety_note": "No pets live in the household, ensuring all selected succulents remain purely decorative without risk of ingestion."
}
